    RestAssured.requestSpecification = WebAdminUtils.buildRequestSpecification(webAdminServer).setBasePath(MailRepositoriesRoutes.MAIL_REPOSITORIES).build();
    RestAssured.enableLoggingOfRequestAndResponseIfValidationFails();
}

